changeSet.sql:
ALTER TABLE delivery_needs ADD COLUMN IF NOT EXISTS announcement_id UUID;
ALTER TABLE delivery_needs ADD COLUMN IF NOT EXISTS parcel_id UUID;
UPDATE delivery_needs SET parcel_id = packet_id WHERE parcel_id IS NULL AND packet_id IS NOT NULL;
ALTER TABLE delivery_needs ALTER COLUMN status DROP NOT NULL;
CREATE INDEX IF NOT EXISTS idx_delivery_needs_announcement_id
    ON delivery_needs (announcement_id) WHERE announcement_id IS NOT NULL;
